package com.payshield.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="payments") public class Payment {
 @Id private UUID id; @Column(nullable=false,precision=19,scale=2) private BigDecimal amount; @Column(nullable=false,length=3) private String currency; @Column(nullable=false) private String merchantReference; @Column(nullable=false) private String customerId; @Column(nullable=false) private String paymentToken; @Enumerated(EnumType.STRING) @Column(nullable=false) private PaymentStatus status; private String failureReason; @Version private long version; @Column(nullable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt;
 protected Payment(){} public Payment(UUID id,BigDecimal amount,String currency,String merchantReference,String customerId,String paymentToken){this.id=id;this.amount=amount;this.currency=currency;this.merchantReference=merchantReference;this.customerId=customerId;this.paymentToken=paymentToken;this.status=PaymentStatus.CREATED;this.createdAt=Instant.now();this.updatedAt=createdAt;}
 public void status(PaymentStatus value){status=value;updatedAt=Instant.now();} public void fail(String reason){failureReason=reason;status(PaymentStatus.FAILED);} public UUID getId(){return id;} public BigDecimal getAmount(){return amount;} public String getCurrency(){return currency;} public String getMerchantReference(){return merchantReference;} public String getCustomerId(){return customerId;} public PaymentStatus getStatus(){return status;} public String getFailureReason(){return failureReason;}
}
